package com.hatsune.lingolens.module.wordasset.bo;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;

/**
 * Normalized result generated by LLM before it is compressed into
 * word_assets.language_payloads.
 *
 * @author hatsune_hitsuzi
 * @since 2026-06-15
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class GeneratedWordAssetBO {

    private String wordKey;

    private String canonicalLanguage;

    private String canonicalWord;

    private List<LanguagePayload> payloads;

    @Data
    @Builder
    @NoArgsConstructor
    @AllArgsConstructor
    public static class LanguagePayload {
        private String lang;
        private String word;
        private String phonetic;
        private String pos;
        private String explanation;
        private String example;
    }
}
